def lookup_loinc(code: str) -> Optional[Dict]:
    """Lookup LOINC test record."""
    return LOINC_CATALOGUE.get(code.strip())

def filter_loinc_by_category(category: str) -> List[Dict]:
    """Retrieve tests within specific clinical diagnostic discipline."""
    cat = category.strip().upper()
    return [t for t in LOINC_CATALOGUE.values() if t["category"] == cat]
